<?php namespace App\Http\Controllers;use App\Models\Branch;use App\Models\HrCandidate;use Illuminate\Http\Request;class HrCandidateController extends AccountBaseController{private function auth(){abort_403(!in_array(user()->permission('edit_employees'),['all','branch'],true));}public function index(){$this->pageTitle = 'Recruitment candidates';$this->auth();$this->candidates=HrCandidate::where('company_id',user()->company_id)->latest()->get();$this->branches=Branch::orderBy('name')->get();return view('hr-candidates.index',$this->data);}public function store(Request $r){$this->auth();$d=$r->validate(['name'=>'required|string|max:255','email'=>'nullable|email','mobile'=>'nullable|string|max:30','branch_id'=>'nullable|exists:branches,id','designation'=>'nullable|string|max:255','notes'=>'nullable|string']);HrCandidate::create($d+['company_id'=>user()->company_id,'created_by'=>user()->id]);return back()->with('success','Candidate staged.');}public function handoff(HrCandidate $candidate){$this->auth();abort_403($candidate->company_id!==user()->company_id||$candidate->status==='converted');$candidate->update(['status'=>'handoff']);return redirect()->route('employees.create',['candidate_id'=>$candidate->id,'name'=>$candidate->name,'email'=>$candidate->email,'mobile'=>$candidate->mobile,'branch_id'=>$candidate->branch_id]);}}
